import { shallowRef } from 'vue'
import type { FloorConfigItem, PropConfigItem } from '../types/scene-config'
import { generateUniqueId } from '../types/scene-config'
import type { EditableEntitySnapshot } from '../types/command'
import type { useSceneStore } from '../stores/scene'
import { InsertEntityCommand } from '../commands/InsertEntityCommand'
import { BatchCommand } from '../commands/BatchCommand'
import type { Command } from '../types/command'

/* ============================================================
 * Clipboard Payload（可序列化格式，为后续系统剪贴板预留）
 * ============================================================ */

interface SplatStudioClipboardPayload {
  app: 'splat-studio'
  version: 1
  items: EditableEntitySnapshot[]
}

/** 粘贴时位置偏移量（避免与原对象完全重叠） */
const PASTE_OFFSET = 1

/* ============================================================
 * 模块级单例（跨组件共享，不走 Pinia 避免 DevTools 序列化问题）
 * ============================================================ */

const clipboardPayload = shallowRef<SplatStudioClipboardPayload | null>(null)

/**
 * 编辑器剪贴板 composable。
 *
 * 第一期为应用内剪贴板（ref），数据结构按可序列化格式设计，
 * 后续要接系统剪贴板时可直接 JSON.stringify(payload)。
 */
export function useEditorClipboard(sceneStore: ReturnType<typeof useSceneStore>) {
  /** 剪贴板是否有内容 */
  function hasClipboard(): boolean {
    return clipboardPayload.value !== null && clipboardPayload.value.items.length > 0
  }

  /**
   * 复制当前选中的 floor/prop 到剪贴板。
   * @returns true = 复制成功
   */
  function copySelected(): boolean {
    const key = sceneStore.selectedConfigKey
    if (!key || key.kind === 'meta') return false

    if (key.kind === 'floor') {
      const snapshot = sceneStore.getFloorSnapshot(key.id)
      if (!snapshot) return false
      clipboardPayload.value = {
        app: 'splat-studio',
        version: 1,
        items: [{ kind: 'floor', data: snapshot }],
      }
      return true
    }

    if (key.kind === 'prop') {
      const snapshot = sceneStore.getPropSnapshot(key.id)
      if (!snapshot) return false
      clipboardPayload.value = {
        app: 'splat-studio',
        version: 1,
        items: [{ kind: 'prop', data: snapshot }],
      }
      return true
    }

    return false
  }

  /**
   * 构造粘贴命令（不执行）。
   * 调用方拿到后 dispatch 即可。
   *
   * @returns Command | null（剪贴板为空时返回 null）
   */
  function createPasteCommand(): Command | null {
    if (!clipboardPayload.value || clipboardPayload.value.items.length === 0) return null

    const items = clipboardPayload.value.items
    // 维护本地 usedIds 避免批量粘贴时生成重复 ID
    const usedIds = sceneStore.collectAllIds()
    const commands: Command[] = []

    for (const item of items) {
      const newId = generateUniqueId(item.kind, usedIds)
      usedIds.push(newId)

      if (item.kind === 'floor') {
        const cloned: FloorConfigItem = {
          ...item.data,
          id: newId,
          position: {
            x: item.data.position.x + PASTE_OFFSET,
            y: item.data.position.y,
            z: item.data.position.z + PASTE_OFFSET,
          },
        }
        commands.push(
          new InsertEntityCommand(sceneStore, { kind: 'floor', data: cloned }, `粘贴 ${newId}`),
        )
      } else {
        const srcData = item.data as PropConfigItem
        const cloned: PropConfigItem = {
          ...srcData,
          id: newId,
          position: {
            x: srcData.position.x + PASTE_OFFSET,
            y: srcData.position.y,
            z: srcData.position.z + PASTE_OFFSET,
          },
        }
        commands.push(
          new InsertEntityCommand(sceneStore, { kind: 'prop', data: cloned }, `粘贴 ${newId}`),
        )
      }
    }

    if (commands.length === 1) return commands[0]
    return new BatchCommand(commands, `粘贴 ${commands.length} 个对象`)
  }

  return {
    hasClipboard,
    copySelected,
    createPasteCommand,
    clipboardPayload,
  }
}
