import { onMounted, onUnmounted } from 'vue'
import { useSceneStore } from '../stores/scene'
import { useHistoryStore } from '../stores/history'
import { RemoveEntityCommand } from '../commands/RemoveEntityCommand'
import { useEditorClipboard } from './useEditorClipboard'
import { isEditableTarget } from '../utils/keyboard'
import { toast } from './useToast'

/**
 * 编辑器快捷键 composable。
 *
 * 负责：
 *   - Ctrl/Cmd + Z：撤销
 *   - Ctrl/Cmd + Shift + Z：重做
 *   - Ctrl/Cmd + Y：重做
 *   - Ctrl/Cmd + C：复制当前选中的 floor/prop
 *   - Ctrl/Cmd + V：粘贴
 *   - Delete / Backspace：删除当前选中的 floor/prop
 *
 * 与 useTransformShortcuts 不冲突：
 *   useTransformShortcuts 已有 `if (e.ctrlKey || e.metaKey) return` 守卫，
 *   Ctrl+Z 等组合键在 transform 层被透传，在 edit 层被消费。
 *
 * @param options.isBlocked - 返回 true 时阻塞所有编辑快捷键（Dialog 打开等）
 */
export function useEditShortcuts(options: {
  isBlocked?: () => boolean
} = {}): void {
  const sceneStore = useSceneStore()
  const historyStore = useHistoryStore()
  const clipboard = useEditorClipboard(sceneStore)

  function dispatchDeleteSelected(): void {
    const key = sceneStore.selectedConfigKey
    if (!key || key.kind === 'meta') return

    if (key.kind === 'floor') {
      const snapshot = sceneStore.getFloorSnapshot(key.id)
      if (!snapshot) return
      historyStore.dispatch(
        new RemoveEntityCommand(sceneStore, { kind: 'floor', data: snapshot }),
      )
      return
    }

    if (key.kind === 'prop') {
      const snapshot = sceneStore.getPropSnapshot(key.id)
      if (!snapshot) return
      historyStore.dispatch(
        new RemoveEntityCommand(sceneStore, { kind: 'prop', data: snapshot }),
      )
    }
  }

  function onKeyDown(e: KeyboardEvent): void {
    if (options.isBlocked?.()) return
    if (isEditableTarget(e.target)) return

    const isMod = e.ctrlKey || e.metaKey

    // --- Ctrl/Cmd + Z / Ctrl/Cmd + Shift + Z / Ctrl/Cmd + Y ---
    if (isMod && e.code === 'KeyZ') {
      e.preventDefault()
      if (e.shiftKey) {
        historyStore.redo()
      } else {
        historyStore.undo()
      }
      return
    }

    if (isMod && e.code === 'KeyY') {
      e.preventDefault()
      historyStore.redo()
      return
    }

    // --- Ctrl/Cmd + C：复制 ---
    if (isMod && e.code === 'KeyC') {
      e.preventDefault()
      const ok = clipboard.copySelected()
      if (ok) {
        const key = sceneStore.selectedConfigKey
        const label = key?.kind === 'floor' || key?.kind === 'prop' ? key.id : ''
        toast.success(`已复制 ${label}`)
      }
      return
    }

    // --- Ctrl/Cmd + V：粘贴 ---
    if (isMod && e.code === 'KeyV') {
      e.preventDefault()
      const command = clipboard.createPasteCommand()
      if (command) {
        historyStore.dispatch(command)
        toast.success(command.label)
      }
      return
    }

    // --- Delete / Backspace（无修饰键） ---
    if (!isMod && !e.shiftKey && !e.altKey && (e.code === 'Delete' || e.code === 'Backspace')) {
      e.preventDefault()
      dispatchDeleteSelected()
    }
  }

  onMounted(() => {
    window.addEventListener('keydown', onKeyDown)
  })

  onUnmounted(() => {
    window.removeEventListener('keydown', onKeyDown)
  })
}
