import * as THREE from 'three'
import { OrbitControls } from 'three/addons/controls/OrbitControls.js'
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js'

/* ── 网格尺寸常量 ── */
const GRID_HALF_SIZE = 50
const GRID_MAJOR_STEP = 10
const GRID_LENGTH = GRID_HALF_SIZE * 2

/* ── 线宽常量（世界单位） ── */
const GRID_MINOR_WIDTH = 0.03
const GRID_MAJOR_WIDTH = 0.12
const AXIS_WIDTH = 0.24
const ORIGIN_CROSS_WIDTH = AXIS_WIDTH
const ORIGIN_CROSS_LENGTH = 0.6

/* ── 颜色常量 ── */
const COLOR_MINOR_X = 0x242424
const COLOR_MINOR_Z = 0x1a1a1a
const COLOR_MAJOR = 0x404040
const COLOR_AXIS_X = 0xff3040
const COLOR_AXIS_Z = 0x1d36ff
const COLOR_ORIGIN_CROSS = 0xffffff

/*
 * ── 渲染层级（renderOrder）──
 * 全部对象统一为不透明材质 + depthTest:false + depthWrite:false，
 * 层级完全且仅由 renderOrder 决定，越大越靠前。
 * 所有平面条 y=0，不再用 y 偏移做层次。
 */
const RENDER_ORDER_MINOR = 1
const RENDER_ORDER_MAJOR = 2
const RENDER_ORDER_AXIS = 3
const RENDER_ORDER_ORIGIN_CROSS = 4

/**
 * Three.js 场景引擎，负责初始化编辑视口与场景参考元素。
 */
export class SceneEngine {
  private scene: THREE.Scene
  private camera: THREE.PerspectiveCamera
  private renderer: THREE.WebGLRenderer
  private controls: OrbitControls
  private rafId: number | null = null
  private resizeObserver: ResizeObserver | null = null
  private container: HTMLElement

  constructor(canvas: HTMLCanvasElement, container: HTMLElement) {
    this.container = container

    // Scene
    this.scene = new THREE.Scene()
    this.scene.background = new THREE.Color(0x000000)

    // Camera
    const { width, height } = container.getBoundingClientRect()
    this.camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 1000)
    this.camera.position.set(15, 12, 15)
    this.camera.lookAt(0, 0, 0)

    // Renderer
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
    })
    this.renderer.setSize(width, height)
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))

    // Controls
    this.controls = new OrbitControls(this.camera, canvas)
    this.controls.enableDamping = true
    this.controls.dampingFactor = 0.08
    this.controls.minDistance = 2
    this.controls.maxDistance = 100

    // Setup scene contents
    this.setupLights()
    this.setupGrid()

    // Observe resize
    this.resizeObserver = new ResizeObserver(() => {
      this.resize()
    })
    this.resizeObserver.observe(container)
  }

  private setupLights(): void {
    const ambient = new THREE.AmbientLight(0xffffff, 0.4)
    this.scene.add(ambient)

    const directional = new THREE.DirectionalLight(0xffffff, 0.6)
    directional.position.set(10, 20, 10)
    this.scene.add(directional)
  }

  /**
   * 构建网格系统。
   * 策略：每个层级的所有条带合并为 1 个 Mesh，共 4 个对象：
   *   辅网格(minor) < 主网格(major) < 主轴(axis) < 白十字(originCross)
   * 全部不透明、depthTest:false、depthWrite:false，
   * 层级仅靠 renderOrder 区分。
   */
  private setupGrid(): void {
    // ── Layer 1: 辅网格（X/Z 方向两色，分别合并为 1 个 Mesh）──
    const minorXGeos: THREE.BufferGeometry[] = []
    const minorZGeos: THREE.BufferGeometry[] = []
    for (let i = -GRID_HALF_SIZE; i <= GRID_HALF_SIZE; i += 1) {
      if (i === 0 || i % GRID_MAJOR_STEP === 0) continue
      minorXGeos.push(this.makeBandGeo('x', i, GRID_MINOR_WIDTH, GRID_LENGTH))
      minorZGeos.push(this.makeBandGeo('z', i, GRID_MINOR_WIDTH, GRID_LENGTH))
    }
    if (minorXGeos.length > 0) {
      this.scene.add(
        this.buildLayerMesh(mergeGeometries(minorXGeos), COLOR_MINOR_X, RENDER_ORDER_MINOR),
      )
      minorXGeos.forEach((g) => g.dispose())
    }
    if (minorZGeos.length > 0) {
      this.scene.add(
        this.buildLayerMesh(mergeGeometries(minorZGeos), COLOR_MINOR_Z, RENDER_ORDER_MINOR),
      )
      minorZGeos.forEach((g) => g.dispose())
    }

    // ── Layer 2: 主网格 ──
    const majorGeos: THREE.BufferGeometry[] = []
    for (let i = -GRID_HALF_SIZE; i <= GRID_HALF_SIZE; i += GRID_MAJOR_STEP) {
      if (i === 0) continue
      majorGeos.push(this.makeBandGeo('x', i, GRID_MAJOR_WIDTH, GRID_LENGTH))
      majorGeos.push(this.makeBandGeo('z', i, GRID_MAJOR_WIDTH, GRID_LENGTH))
    }
    if (majorGeos.length > 0) {
      this.scene.add(
        this.buildLayerMesh(mergeGeometries(majorGeos), COLOR_MAJOR, RENDER_ORDER_MAJOR),
      )
      majorGeos.forEach((g) => g.dispose())
    }

    // ── Layer 3: 主轴（红 X / 蓝 Z）──
    const axisXGeo = this.makeBandGeo('x', 0, AXIS_WIDTH, GRID_LENGTH)
    this.scene.add(this.buildLayerMesh(axisXGeo, COLOR_AXIS_X, RENDER_ORDER_AXIS))

    const axisZGeo = this.makeBandGeo('z', 0, AXIS_WIDTH, GRID_LENGTH)
    this.scene.add(this.buildLayerMesh(axisZGeo, COLOR_AXIS_Z, RENDER_ORDER_AXIS))

    // ── Layer 4: 原点白十字 ──
    const crossGeos = [
      this.makeBandGeo('x', 0, ORIGIN_CROSS_WIDTH, ORIGIN_CROSS_LENGTH),
      this.makeBandGeo('z', 0, ORIGIN_CROSS_WIDTH, ORIGIN_CROSS_LENGTH),
    ]
    const crossMerged = mergeGeometries(crossGeos)
    this.scene.add(this.buildLayerMesh(crossMerged, COLOR_ORIGIN_CROSS, RENDER_ORDER_ORIGIN_CROSS))
    crossGeos.forEach((g) => g.dispose())
  }

  /**
   * 创建一条平面条的几何体（已旋转到 XZ 平面、已定位）。
   * 返回的 geometry 可直接用于 merge。
   */
  private makeBandGeo(
    direction: 'x' | 'z',
    offset: number,
    width: number,
    length: number,
  ): THREE.BufferGeometry {
    const isX = direction === 'x'
    const geo = isX
      ? new THREE.PlaneGeometry(length, width)
      : new THREE.PlaneGeometry(width, length)

    // 旋转到 XZ 平面 + 定位（先 bake 到顶点里，merge 才不会丢变换）
    const matrix = new THREE.Matrix4()
    matrix.makeRotationX(-Math.PI / 2)
    const posMatrix = new THREE.Matrix4()
    posMatrix.makeTranslation(isX ? 0 : offset, 0, isX ? offset : 0)
    matrix.premultiply(posMatrix)
    geo.applyMatrix4(matrix)

    return geo
  }

  /**
   * 把合并后的几何体包装成最终 Mesh，统一材质配置。
   * 全部不透明、关闭深度测试/写入，用 renderOrder 做唯一排序。
   */
  private buildLayerMesh(
    geometry: THREE.BufferGeometry,
    color: number,
    renderOrder: number,
  ): THREE.Mesh {
    const material = new THREE.MeshBasicMaterial({
      color,
      toneMapped: false,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
    })
    const mesh = new THREE.Mesh(geometry, material)
    mesh.renderOrder = renderOrder
    mesh.frustumCulled = false
    return mesh
  }



  private resize(): void {
    const { width, height } = this.container.getBoundingClientRect()
    if (width === 0 || height === 0) return
    this.camera.aspect = width / height
    this.camera.updateProjectionMatrix()
    this.renderer.setSize(width, height)
  }

  start(): void {
    const animate = () => {
      this.rafId = requestAnimationFrame(animate)
      this.controls.update()
      this.renderer.render(this.scene, this.camera)
    }
    animate()
  }

  stop(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId)
      this.rafId = null
    }
  }

  dispose(): void {
    this.stop()
    this.resizeObserver?.disconnect()
    this.controls.dispose()

    this.scene.traverse((child) => {
      if (child instanceof THREE.Mesh) {
        child.geometry?.dispose()
        if (Array.isArray(child.material)) {
          child.material.forEach((material) => material.dispose())
        } else {
          child.material?.dispose()
        }
      }
      if (child instanceof THREE.Line) {
        child.geometry?.dispose()
        if (child.material instanceof THREE.Material) {
          child.material.dispose()
        }
      }
    })

    this.renderer.dispose()
  }

  getCameraPosition(): { x: number; y: number; z: number } {
    return {
      x: Math.round(this.camera.position.x * 100) / 100,
      y: Math.round(this.camera.position.y * 100) / 100,
      z: Math.round(this.camera.position.z * 100) / 100,
    }
  }

  /**
   * 暴露相机四元数，供 H5 overlay 的坐标轴 gizmo 投影世界轴到屏幕空间。
   * 返回新对象避免外部修改影响内部状态；给 null 表示尚未就绪（理论上构造后即可用，留 null 仅做接口对称）。
   */
  getCameraQuaternion(): THREE.Quaternion {
    return this.camera.quaternion.clone()
  }
}
