import { computed, markRaw, shallowRef } from 'vue'
import { defineStore } from 'pinia'
import type { Command } from '../types/command'

/** 撤销栈最大深度（经验值，覆盖一个编辑会话的常见操作） */
const MAX_HISTORY = 50

export const useHistoryStore = defineStore('history', () => {
  /**
   * 使用 shallowRef 而非 ref：
   * Command 是带方法的 class 实例，不需要 Vue 深度代理。
   * 配合 markRaw 使用，避免 DevTools 序列化问题和不必要的响应式开销。
   */
  const undoStack = shallowRef<Command[]>([])
  const redoStack = shallowRef<Command[]>([])

  const canUndo = computed(() => undoStack.value.length > 0)
  const canRedo = computed(() => redoStack.value.length > 0)

  /** 当前栈顶命令的 label（用于菜单展示 "撤销 移动 floor_1"） */
  const undoLabel = computed(() => {
    const s = undoStack.value
    return s.length > 0 ? s[s.length - 1].label : ''
  })
  const redoLabel = computed(() => {
    const s = redoStack.value
    return s.length > 0 ? s[s.length - 1].label : ''
  })

  /**
   * 执行命令并推入 undo 栈。
   * 新操作会清空 redo 栈（标准编辑器行为）。
   */
  function dispatch(command: Command): boolean {
    const rawCommand = markRaw(command)

    const ok = rawCommand.execute()
    if (!ok) return false

    undoStack.value = [...undoStack.value, rawCommand].slice(-MAX_HISTORY)
    redoStack.value = []
    return true
  }

  /**
   * 将已执行过的命令直接推入 undo 栈（不调用 execute）。
   *
   * 适用场景：Gizmo 拖拽 / modalAxisDrag 等外部已直接完成 store 写入的路径。
   * 调用方保证：command 的 execute 逻辑对应的状态变更已经发生。
   * undo/redo 时仍走 command.undo()/execute() 正常路径。
   */
  function pushExecuted(command: Command): void {
    const rawCommand = markRaw(command)
    undoStack.value = [...undoStack.value, rawCommand].slice(-MAX_HISTORY)
    redoStack.value = []
  }

  /** 撤销栈顶命令 */
  function undo(): boolean {
    const stack = undoStack.value
    if (stack.length === 0) return false
    const command = stack[stack.length - 1]

    const ok = command.undo()
    if (!ok) return false

    undoStack.value = stack.slice(0, -1)
    redoStack.value = [...redoStack.value, command].slice(-MAX_HISTORY)
    return true
  }

  /** 重做栈顶命令 */
  function redo(): boolean {
    const stack = redoStack.value
    if (stack.length === 0) return false
    const command = stack[stack.length - 1]

    const ok = command.execute()
    if (!ok) return false

    redoStack.value = stack.slice(0, -1)
    undoStack.value = [...undoStack.value, command].slice(-MAX_HISTORY)
    return true
  }

  /** 清空所有历史（切场景 / 导入配置 / 卸载场景时调用） */
  function clear(): void {
    undoStack.value = []
    redoStack.value = []
  }

  return {
    undoStack,
    redoStack,
    canUndo,
    canRedo,
    undoLabel,
    redoLabel,
    dispatch,
    pushExecuted,
    undo,
    redo,
    clear,
  }
})
