<!--
  AxisLockToast.vue — splat-studio 轴锁 / 模式切换瞬时反馈

  Blender 风格顶部居中短提示，监听 axisLock / activeTool 变化：
    · 淡入 300ms → 停留 3000ms → 淡出 500ms
    · 连续变更会重置计时器（取消上一次的 hide 定时）

  @changelog
  | 版本   | 变更说明                                                                                                                                                              | 关联                                                                                             |
  | v1.0.0 | 骨架创建：空 template + 淡入淡出占位 class（不含 watch 与文案格式化）                                                                                                  | REQ: 20260506-三模式变换 TECH: 05_design_tech.md §3.5.2 (A06 骨架)                                |
  | v1.1.0 | **业务填充 (B12+B13+B14)**：                                                                                                                                          | REQ: 20260506-三模式变换 TECH: 05_design_tech.md §3.5.2                                           |
  |        |   · B12 动效：watch([axisLock, activeTool])，300ms fade-in / 3000ms hold / 500ms fade-out，切换时重置计时                                                               |                                                                                                  |
  |        |   · B13 文案：`${mode} ${axis}`（如 "G X" / "R Y" / "T Z"）；仅模式变化（无锁）显示"移动/旋转/缩放"；解锁显示"解除轴锁"                                                   |                                                                                                  |
  |        |   · B14 挂载：ViewportOverlay.vue 内（pointer-none 容器，不拦截鼠标）                                                                                                   |                                                                                                  |
  |        |   · 首次挂载（onMounted 前的 immediate watch）不触发 toast，避免刷新闪一下"移动"                                                                                        |                                                                                                  |
  /@changelog

  设计要点：
    - `visible` + `text` 分离：visible=false 仍保留 text 直到彻底淡出，避免淡出中途文本消失。
    - 采用 `<Transition name="toast">` 原生 CSS 过渡，不依赖任何 UI 库；class 与 tokens.css 无强耦合。
    - 语义 accessible：aria-live="polite" + role="status"，读屏软件在用户操作暂停后播报。

  @author v_djlzhou
-->
<script setup lang="ts">
import { ref, watch, onBeforeUnmount } from 'vue'
import { storeToRefs } from 'pinia'
import { useEditorStore } from '../../stores/editor'
import type { AxisLock, ToolType } from '../../types/editor'

defineOptions({ name: 'AxisLockToast' })

/* ------------------------------------------------------------------ *
 *  动效常量（与 tech-design §3.5.2 对齐）
 * ------------------------------------------------------------------ */

/** 淡入时长（ms），与 CSS `--toast-fade-in` 保持一致 */
const FADE_IN_MS = 300
/** 保持显示时长（ms），从淡入结束起算到淡出开始 */
const HOLD_MS = 3000
/** 淡出时长（ms），与 CSS `--toast-fade-out` 保持一致 */
const FADE_OUT_MS = 500

/* ------------------------------------------------------------------ *
 *  文案格式化
 * ------------------------------------------------------------------ */

/**
 * 工具 → 模式字母 / 模式中文。
 *
 * 仅 move / rotate / scale 在轴锁语境下有意义；其他工具返回 null
 * （切到 select / region-select 时不弹 toast，语义上不属于"变换操作"）。
 */
const MODE_LABEL: Record<ToolType, { letter: string; zh: string } | null> = {
  select: null,
  'region-select': null,
  move: { letter: 'G', zh: '移动' },
  rotate: { letter: 'R', zh: '旋转' },
  scale: { letter: 'T', zh: '缩放' },
}

function formatText(tool: ToolType, axis: AxisLock): string | null {
  const info = MODE_LABEL[tool]
  // 非三变换模式：不显示
  if (!info) return null
  if (axis !== null) {
    // "G X" / "R Y" / "T Z"
    return `${info.letter} ${axis}`
  }
  // 模式切换但无轴锁：显示中文模式名
  return info.zh
}

/* ------------------------------------------------------------------ *
 *  响应式状态
 * ------------------------------------------------------------------ */

const editorStore = useEditorStore()
const { axisLock, activeTool } = storeToRefs(editorStore)

const text = ref('')
const visible = ref(false)

let hideTimer: ReturnType<typeof setTimeout> | null = null

function scheduleHide(): void {
  if (hideTimer !== null) clearTimeout(hideTimer)
  hideTimer = setTimeout(() => {
    visible.value = false
    hideTimer = null
  }, HOLD_MS)
}

function showToast(next: string): void {
  text.value = next
  visible.value = true
  scheduleHide()
}

/* ------------------------------------------------------------------ *
 *  Watch：axisLock / activeTool 变化驱动 toast
 *
 *  immediate=false：首次挂载不弹，避免页面刷新时闪现"移动"。
 *  使用 deep=false（默认）：只关心 ref 值本身，不关心引用稳定性。
 * ------------------------------------------------------------------ */

watch([axisLock, activeTool], ([nextLock, nextTool], [prevLock, prevTool]) => {
  // 特化：从"有锁"切换到"无锁"（Escape 清锁 / toggle 同轴解锁）
  //   → 显示"解除轴锁"（轴锁是主体事件，工具名不重要）
  if (prevLock !== null && nextLock === null && nextTool === prevTool) {
    showToast('解除轴锁')
    return
  }

  // 常规：按 "mode + axis" 格式化
  const formatted = formatText(nextTool, nextLock)
  if (formatted === null) return // 切到 select / region-select：静默
  showToast(formatted)
})

onBeforeUnmount(() => {
  if (hideTimer !== null) clearTimeout(hideTimer)
})
</script>

<template>
  <Transition name="toast">
    <div
      v-if="visible"
      class="axis-lock-toast"
      role="status"
      aria-live="polite"
    >
      {{ text }}
    </div>
  </Transition>
</template>

<style scoped>
.axis-lock-toast {
  pointer-events: none;
  position: absolute;
  top: 80px;
  left: 50%;
  transform: translateX(-50%);
  padding: 8px 20px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.78);
  color: #fff;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 18px;
  font-weight: 500;
  letter-spacing: 0.05em;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  user-select: none;
  white-space: nowrap;
}

/* Transition: enter = 300ms fade-in, leave = 500ms fade-out（与常量一致）*/
.toast-enter-active {
  transition: opacity 300ms ease-out;
}
.toast-leave-active {
  transition: opacity 500ms ease-in;
}
.toast-enter-from,
.toast-leave-to {
  opacity: 0;
}
.toast-enter-to,
.toast-leave-from {
  opacity: 1;
}
</style>
