<script setup lang="ts">
import { ref, computed, nextTick, onMounted, onUnmounted } from 'vue'
import { useSceneStore } from '../../stores/scene'
import { useHistoryStore } from '../../stores/history'
import { InsertEntityCommand, RemoveEntityCommand } from '../../commands'
import { usePanelsStore } from '../../stores/panels'
import { createDefaultFloor, createDefaultProp } from '../../types/scene-config'
import FloatingPanel from './FloatingPanel.vue'
import {
  IconFloor,
  IconProp,
  IconFolder,
  IconLink,
  IconExpand,
  IconCollapse,
} from '../../utils/icons'
import { ChevronDown } from 'lucide-vue-next'
import type { MetaNodeObject } from '../../types/scene'
import { PROP_CATEGORY_LABELS } from '../../types/scene-config'
import type { ConfigValidationError } from '../../utils/sceneConfigValidator'
import { confirm } from '../../composables/useConfirm'

const sceneStore = useSceneStore()
const historyStore = useHistoryStore()
const panelsStore = usePanelsStore()

const emit = defineEmits<{
  (e: 'open-scene-url'): void
  (e: 'load-scene-url', url: string): void
}>()

/* ===================================================================
 * 场景管理卡片（v1.0.0 保留）
 * ================================================================ */

const isLoaded = computed(() => sceneStore.sdkSceneUrl !== null)

const sceneDisplayName = computed(() => {
  if (!isLoaded.value) return ''
  const meta = sceneStore.sceneMeta
  if (meta?.sceneName) return meta.sceneName
  try {
    const url = sceneStore.sdkSceneUrl!
    const pathname = new URL(url).pathname
    const segments = pathname.split('/').filter(Boolean)
    return segments[segments.length - 1] || url
  } catch {
    return sceneStore.sdkSceneUrl || '未命名场景'
  }
})

function handleOpenSceneUrl() {
  emit('open-scene-url')
}
function handleUnloadScene() {
  sceneStore.unloadScene()
}

/* ===================================================================
 * v4.1.0: 场景快选下拉（Split Button 右侧 ▼）
 *
 * 数据来源：wuji API scene_pos_config_v2（同 h5 主页 ModelList.vue）
 * 按需加载：首次点 ▼ 才发请求，避免页面初始化时浪费请求
 * 失败策略：静默显示"暂无可用场景"，sceneOptionsLoaded=false 允许下次重试
 * 关闭时机：点列表外部 / 点条目 / Escape
 * ================================================================ */

interface SceneOption {
  id: string
  name: string       // 中文名，显示在列表里
  modelUrlV2: string // meta.json URL，传给 loadSceneFromUrl
}

const SCENE_API_PATH = '/wuji_cache/object?appid=my_buddy_test&schemaid=scene_pos_config_v2&schemakey=31bfc3054bb54a299ccf2c06a33162d9'

/** Split Button 本体的 DOM 引用（用于计算下拉列表位置） */
const splitBtnRef = ref<HTMLElement | null>(null)
const dropdownOpen = ref(false)
const sceneOptions = ref<SceneOption[]>([])
const sceneOptionsLoading = ref(false)
const sceneOptionsLoaded = ref(false)

/**
 * 下拉列表的固定定位样式。
 * 在 Teleport 到 body 后，通过 getBoundingClientRect 计算 Split Button 的视口位置，
 * 再换算为 fixed 坐标，避免被 FloatingPanel 的 overflow:hidden 裁切。
 */
interface DropdownStyle {
  top: string
  left: string
  width: string
}
const dropdownStyle = ref<DropdownStyle>({ top: '0px', left: '0px', width: '0px' })

function calcDropdownStyle(): void {
  if (!splitBtnRef.value) return
  const rect = splitBtnRef.value.getBoundingClientRect()
  dropdownStyle.value = {
    top: `${rect.bottom + 4}px`,
    left: `${rect.left}px`,
    width: `${rect.width}px`,
  }
}

/** 判断某条 option 是否是当前已加载的场景 */
function isCurrentScene(option: SceneOption): boolean {
  return sceneStore.sdkSceneUrl === option.modelUrlV2
}

/** 按需拉取场景列表（已拉取或正在拉取时跳过） */
async function fetchSceneOptions(): Promise<void> {
  if (sceneOptionsLoaded.value || sceneOptionsLoading.value) return
  sceneOptionsLoading.value = true
  try {
    const base = import.meta.env.MODE === 'production'
      ? 'https://api.wuji.qq.com/x/api'
      : '/api_wuji'
    const res = await fetch(`${base}${SCENE_API_PATH}`)
    const json = await res.json()
    sceneOptions.value = (json.data ?? []).filter(
      (item: SceneOption) => item.modelUrlV2 && item.name,
    )
    sceneOptionsLoaded.value = true
  } catch {
    // 静默失败：允许下次重试（sceneOptionsLoaded 保持 false）
    sceneOptions.value = []
  } finally {
    sceneOptionsLoading.value = false
  }
}

function openDropdown(): void {
  calcDropdownStyle()
  dropdownOpen.value = true
  void fetchSceneOptions()
  // 下一帧再挂监听，避免本次点击事件立刻触发关闭
  nextTick(() => {
    window.addEventListener('click', handleOutsideClick, true)
  })
}

function closeDropdown(): void {
  dropdownOpen.value = false
  window.removeEventListener('click', handleOutsideClick, true)
}

function toggleDropdown(): void {
  if (dropdownOpen.value) {
    closeDropdown()
  } else {
    openDropdown()
  }
}

function handleOutsideClick(e: MouseEvent): void {
  // 点击 Split Button 本身由 toggleDropdown 处理（.stop 已阻止冒泡）
  // 点击下拉列表内部不关闭
  const target = e.target as Node
  if (splitBtnRef.value?.contains(target)) return
  closeDropdown()
}

function handleSelectScene(option: SceneOption): void {
  closeDropdown()
  emit('load-scene-url', option.modelUrlV2)
}

function handleDropdownKeyDown(e: KeyboardEvent): void {
  if (e.key === 'Escape' && dropdownOpen.value) {
    e.stopPropagation() // 避免触发 SplatStudio 的全局 ESC 处理
    closeDropdown()
  }
}

onMounted(() => window.addEventListener('keydown', handleDropdownKeyDown))
onUnmounted(() => {
  window.removeEventListener('keydown', handleDropdownKeyDown)
  window.removeEventListener('click', handleOutsideClick, true)
})

/* ===================================================================
 * v2.0.0: Tab 切换
 * ui-ux-pro-max 主役原则: 激活态加粗 + accent 底边，未激活态 text-subtle
 * ================================================================ */

type TabKey = 'edit' | 'meta'
const activeTab = ref<TabKey>('edit')

/* ===================================================================
 * 编辑 Tab：Meta 行 + Floor 分组 + Prop 分组
 * ================================================================ */

const floorExpanded = ref(true)
const propExpanded = ref(true)

const sceneMetaLabel = computed(() => {
  return (
    sceneStore.sceneConfig.name ||
    sceneStore.sceneConfig.sceneId ||
    '未命名场景'
  )
})

const isMetaSelected = computed(
  () => sceneStore.selectedConfigKey?.kind === 'meta',
)

function selectMeta() {
  sceneStore.selectConfig({ kind: 'meta' })
}

/**
 * v3.4.1: scene 级错误聚合
 *
 * 与 floor/prop 不同，scene 级错误的 path 没有 \[i\] 数组下标前缀，
 * 直接是 "sceneId" / "name" / "bounds"（见 sceneConfigValidator）。
 * 用「path 不以 floor[ 或 prop[ 开头」反向识别，未来 validator 新增 scene 级
 * 字段（如 sceneVersion、tags）时无需改动这里。
 */
const sceneMetaError = computed<ErrorBucket | undefined>(() => {
  const errs = sceneStore.configValidationErrors.filter(
    (e) => !e.path.startsWith('floor[') && !e.path.startsWith('prop['),
  )
  if (errs.length === 0) return undefined
  const seen = new Set<string>()
  const lines: string[] = []
  for (const e of errs) {
    if (seen.has(e.message)) continue
    seen.add(e.message)
    lines.push(e.message)
  }
  return {
    errors: errs,
    summary: `${lines.length} 项配置不完整：\n· ${lines.join('\n· ')}`,
  }
})

function handleSceneMetaErrorClick(): void {
  selectMeta()
  panelsStore.setVisibility('inspector', true)
}
function selectFloor(id: string) {
  sceneStore.selectConfig({ kind: 'floor', id })
}
function selectProp(id: string) {
  sceneStore.selectConfig({ kind: 'prop', id })
}
/** 双击行 → 选中 + 相机聚焦（v3.2.0） */
function focusFloor(id: string) {
  sceneStore.focusOnFloor(id)
}
function focusProp(id: string) {
  sceneStore.focusOnProp(id)
}
function isFloorSelected(id: string): boolean {
  const k = sceneStore.selectedConfigKey
  return k?.kind === 'floor' && k.id === id
}
function isPropSelected(id: string): boolean {
  const k = sceneStore.selectedConfigKey
  return k?.kind === 'prop' && k.id === id
}

/* ===================================================================
 * v3.4.0: 字段校验提示（前置可见）
 *
 * 数据流：sceneStore.configValidationErrors（已存在的 computed）
 *   → 按 path 前缀（"floor[i]" / "prop[i]"）反查 id
 *   → 聚合为 Map<id, ConfigValidationError[]>
 *
 * 为什么按 i（数组下标）反查而不是直接按 id：
 *   validator 给的 path 是 "floor[3].name" 这种数组下标形态，
 *   在层级行渲染时我们拿到的是 item.id；用下标作为桥梁一次遍历完成映射，
 *   O(n) 复杂度，100+100 规模下对性能无感。
 * ================================================================ */

interface ErrorBucket {
  errors: ConfigValidationError[]
  /** 用户可读的简要说明（tooltip 用），形如 "name 为必填项；id 为必填项" */
  summary: string
}

function buildErrorMap(
  prefix: 'floor' | 'prop',
  items: ReadonlyArray<{ id: string }>,
  allErrors: readonly ConfigValidationError[],
): Map<string, ErrorBucket> {
  const map = new Map<string, ErrorBucket>()
  // path 形如 "floor[3].name" 或 "floor[3].id"
  const pattern = new RegExp(`^${prefix}\\[(\\d+)\\]`)
  for (const err of allErrors) {
    const m = pattern.exec(err.path)
    if (!m) continue
    const idx = Number(m[1])
    const item = items[idx]
    if (!item) continue
    let bucket = map.get(item.id)
    if (!bucket) {
      bucket = { errors: [], summary: '' }
      map.set(item.id, bucket)
    }
    bucket.errors.push(err)
  }
  // 生成 summary（去重 message，避免相同信息重复）
  for (const bucket of map.values()) {
    const seen = new Set<string>()
    const lines: string[] = []
    for (const e of bucket.errors) {
      if (seen.has(e.message)) continue
      seen.add(e.message)
      lines.push(e.message)
    }
    bucket.summary = `${lines.length} 项配置不完整：\n· ${lines.join('\n· ')}`
  }
  return map
}

const floorErrorsMap = computed(() =>
  buildErrorMap(
    'floor',
    sceneStore.sceneConfig.floor,
    sceneStore.configValidationErrors,
  ),
)
const propErrorsMap = computed(() =>
  buildErrorMap(
    'prop',
    sceneStore.sceneConfig.prop,
    sceneStore.configValidationErrors,
  ),
)

function getFloorError(id: string): ErrorBucket | undefined {
  return floorErrorsMap.value.get(id)
}
function getPropError(id: string): ErrorBucket | undefined {
  return propErrorsMap.value.get(id)
}

/**
 * 点击警示标 → 选中该项 + 强制显示 InspectorPanel
 *
 * 用户可能在专注观察 viewport 时把 inspector 关掉了；点警示标的本意就是
 * "我要修这个错"，所以同时把 inspector 拉起来是符合意图的次要副作用。
 */
function handleFloorErrorClick(id: string): void {
  selectFloor(id)
  panelsStore.setVisibility('inspector', true)
}
function handlePropErrorClick(id: string): void {
  selectProp(id)
  panelsStore.setVisibility('inspector', true)
}

function addFloor() {
  const item = createDefaultFloor(sceneStore.collectAllIds())
  historyStore.dispatch(new InsertEntityCommand(sceneStore, { kind: 'floor', data: item }))
  floorExpanded.value = true
}
function addProp() {
  const item = createDefaultProp(sceneStore.collectAllIds())
  historyStore.dispatch(new InsertEntityCommand(sceneStore, { kind: 'prop', data: item }))
  propExpanded.value = true
}
async function removeFloor(id: string, name: string) {
  const label = name || id
  const ok = await confirm({
    title: '删除地面',
    message: `确定要删除「${label}」吗？`,
    confirmText: '删除',
    kind: 'danger',
  })
  if (!ok) return
  const snapshot = sceneStore.getFloorSnapshot(id)
  if (!snapshot) return
  historyStore.dispatch(new RemoveEntityCommand(sceneStore, { kind: 'floor', data: snapshot }))
}
async function removeProp(id: string, name: string) {
  const label = name || id
  const ok = await confirm({
    title: '删除对象',
    message: `确定要删除「${label}」吗？`,
    confirmText: '删除',
    kind: 'danger',
  })
  if (!ok) return
  const snapshot = sceneStore.getPropSnapshot(id)
  if (!snapshot) return
  historyStore.dispatch(new RemoveEntityCommand(sceneStore, { kind: 'prop', data: snapshot }))
}

/* ===================================================================
 * v3.0.0: 创建驱动标注（REQ 20260427）
 *
 * 4 处"+新增"按钮的新交互：
 *   1. 未加载场景 → 禁用（:disabled + tooltip 提示）
 *   2. 已加载 + 当前意图非 X → 点击 = startCreateFloor/Prop(X)（进框选态）
 *   3. 已加载 + 当前意图为 X → 点击 = requestCancelSelection（就近撤销，CLARIFY-Q3）
 * ================================================================ */

const canCreate = computed(() => sceneStore.sdkSceneUrl !== null)
const isCreatingFloor = computed(() => sceneStore.pendingCreateKind === 'floor')
const isCreatingProp = computed(() => sceneStore.pendingCreateKind === 'prop')

function handleAddFloorClick() {
  if (!canCreate.value) return
  if (isCreatingFloor.value) {
    sceneStore.requestCancelSelection()
  } else {
    sceneStore.startCreateFloor()
    floorExpanded.value = true // 保持原"展开分组"视觉心智
  }
}
function handleAddPropClick() {
  if (!canCreate.value) return
  if (isCreatingProp.value) {
    sceneStore.requestCancelSelection()
  } else {
    sceneStore.startCreateProp()
    propExpanded.value = true
  }
}

/* ===================================================================
 * 元数据 Tab：过滤 objects 中 type==='meta' 的只读节点
 * （CLARIFY Q1 互斥选中：调用 selectMetaNode）
 * ================================================================ */

const metaNodes = computed(() =>
  sceneStore.objects.filter((o) => o.type === 'meta') as MetaNodeObject[],
)
const sceneRootExpanded = ref(true)

function selectMetaNode(id: string) {
  sceneStore.selectMetaNode(id)
}
function isMetaNodeSelected(id: string): boolean {
  return sceneStore.selectedObjectId === id
}
</script>

<template>
  <FloatingPanel
    title="场景 (Scene)"
    :icon="IconFolder"
    position="left-top"
    :width="280"
    data-tour="hierarchy-panel"
  >
    <div class="flex flex-col h-full">
      <!-- ========== 场景管理卡片（v1.0.0 保留） ========== -->
      <div class="flex-shrink-0 pb-3 border-b border-border">
        <template v-if="!isLoaded">
          <!-- v4.1.0: Split Button — 左区打开 Dialog，右区展开场景快选下拉 -->
          <!-- ref 挂在 Split Button 上，用于 getBoundingClientRect 计算下拉位置 -->
          <div
            ref="splitBtnRef"
            data-tour="open-scene-btn"
            class="flex w-full rounded-md overflow-hidden
                   bg-accent text-white text-xs font-medium"
          >
            <!-- 左区：打开 URL 输入 Dialog -->
            <button
              class="flex flex-1 items-center justify-center gap-2 px-3 py-2.5
                     hover:bg-white/10 active:bg-white/20
                     transition-colors duration-100 cursor-pointer"
              @click="handleOpenSceneUrl"
            >
              <IconLink :size="14" />
              <span>打开场景 URL</span>
            </button>

            <!-- 竖分割线 -->
            <div class="w-px bg-white/20 my-1.5 shrink-0" />

            <!-- 右区：展开场景快选列表 -->
            <button
              class="w-8 flex items-center justify-center
                     hover:bg-white/10 active:bg-white/20
                     transition-colors duration-100 cursor-pointer shrink-0"
              :title="dropdownOpen ? '收起场景列表' : '从预设场景中选择'"
              @click.stop="toggleDropdown"
            >
              <ChevronDown
                :size="14"
                :class="['transition-transform duration-150', dropdownOpen ? 'rotate-180' : '']"
              />
            </button>
          </div>

          <!-- 下拉列表：Teleport 到 body，fixed 定位，彻底脱离 FloatingPanel overflow:hidden -->
          <Teleport to="body">
            <Transition
              enter-active-class="transition-all duration-150 ease-out"
              enter-from-class="opacity-0 -translate-y-1"
              enter-to-class="opacity-100 translate-y-0"
              leave-active-class="transition-all duration-100 ease-in"
              leave-from-class="opacity-100 translate-y-0"
              leave-to-class="opacity-0 -translate-y-1"
            >
              <div
                v-if="dropdownOpen"
                class="fixed z-[9999] bg-[#1e1e22] border border-border rounded-md shadow-lg
                       overflow-hidden max-h-60 overflow-y-auto
                       [&::-webkit-scrollbar]:w-1
                       [&::-webkit-scrollbar-track]:bg-transparent
                       [&::-webkit-scrollbar-thumb]:bg-white/20
                       [&::-webkit-scrollbar-thumb]:rounded-full
                       [&::-webkit-scrollbar-thumb:hover]:bg-white/30"
                :style="dropdownStyle"
              >
                <!-- 加载中 -->
                <div
                  v-if="sceneOptionsLoading"
                  class="flex items-center gap-2 px-3 py-2.5 text-xs text-text-subtle"
                >
                  <svg
                    class="w-3 h-3 animate-spin shrink-0"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                  >
                    <path d="M21 12a9 9 0 1 1-6.219-8.56" />
                  </svg>
                  <span>加载场景列表...</span>
                </div>

                <!-- 空态 -->
                <div
                  v-else-if="sceneOptions.length === 0"
                  class="px-3 py-2.5 text-xs text-text-subtle text-center"
                >
                  暂无可用场景
                </div>

                <!-- 场景列表 -->
                <template v-else>
                  <button
                    v-for="option in sceneOptions"
                    :key="option.id"
                    class="w-full flex items-center gap-2 px-3 py-2 text-xs text-left
                           hover:bg-bg-hover transition-colors duration-100 cursor-pointer"
                    :class="isCurrentScene(option) ? 'text-accent' : 'text-text-secondary'"
                    @click="handleSelectScene(option)"
                  >
                    <span
                      class="w-1.5 h-1.5 rounded-full shrink-0 transition-colors"
                      :class="isCurrentScene(option) ? 'bg-accent' : 'bg-transparent'"
                    />
                    <span class="truncate">{{ option.name }}</span>
                  </button>
                </template>
              </div>
            </Transition>
          </Teleport>
        </template>

        <template v-else>
          <div class="flex items-start gap-2">
            <div class="flex-1 min-w-0">
              <div class="flex items-center gap-1.5 mb-0.5">
                <span class="inline-block w-1.5 h-1.5 rounded-full bg-accent shrink-0" />
                <span class="text-xs font-medium text-text-primary truncate">
                  {{ sceneDisplayName }}
                </span>
              </div>
              <div
                class="text-[10px] text-text-subtle font-mono truncate pl-3"
                :title="sceneStore.sdkSceneUrl ?? ''"
              >
                {{ sceneStore.sdkSceneUrl }}
              </div>
            </div>
            <button
              class="shrink-0 text-[10px] text-text-subtle hover:text-danger
                     transition-colors duration-100 cursor-pointer py-0.5 px-1 -mx-1 -my-0.5 rounded
                     hover:bg-danger/10"
              title="关闭场景"
              @click="handleUnloadScene"
            >
              关闭
            </button>
          </div>
        </template>
      </div>

      <!-- ==========================================================
        v3.4.2: 未加载场景时整段 Tab 区不渲染，改为中央引导空态。
        - 修复 v3.4.1 在空 sceneConfig 上误报必填字段的副作用
        - 消除 Tab Bar / 空 Floor 分组 / disabled CTA 等空架子视觉噪音
        - 顶部场景管理卡片已有 CTA，这里不再重复（单一焦点原则）
        ========================================================== -->
      <template v-if="isLoaded">
      <!-- ========== v2.0.0 Tab Bar（ui-ux-pro-max: 激活态唯一强调） ========== -->
      <div
        class="flex-shrink-0 flex items-center gap-4 px-1 pt-2 pb-0 border-b border-border"
      >
        <button
          :class="[
            'relative h-7 text-xs transition-colors cursor-pointer select-none px-1',
            activeTab === 'edit'
              ? 'text-text-primary font-semibold'
              : 'text-text-subtle hover:text-text-secondary',
          ]"
          @click="activeTab = 'edit'"
        >
          编辑
          <span
            v-if="activeTab === 'edit'"
            class="absolute left-0 right-0 -bottom-px h-[2px] bg-accent rounded-t"
          />
        </button>
        <button
          :class="[
            'relative h-7 text-xs transition-colors cursor-pointer select-none px-1',
            activeTab === 'meta'
              ? 'text-text-primary font-semibold'
              : 'text-text-subtle hover:text-text-secondary',
          ]"
          @click="activeTab = 'meta'"
        >
          元数据
          <span
            v-if="activeTab === 'meta'"
            class="absolute left-0 right-0 -bottom-px h-[2px] bg-accent rounded-t"
          />
        </button>
      </div>

      <!-- ========== Tab: 编辑（scene-config 编辑） ========== -->
      <div
        v-if="activeTab === 'edit'"
        class="flex-1 min-h-0 pt-2 overflow-y-auto text-xs flex flex-col max-h-[50vh]
               [&::-webkit-scrollbar]:w-1
               [&::-webkit-scrollbar-track]:bg-transparent
               [&::-webkit-scrollbar-thumb]:bg-white/20
               [&::-webkit-scrollbar-thumb]:rounded-full
               [&::-webkit-scrollbar-thumb:hover]:bg-white/30"
      >
        <!-- Meta 行：唯一主役 —— 场景名（点击选中） -->
        <div
          :class="[
            'flex items-center gap-1.5 h-7 px-2 rounded-md cursor-pointer transition-colors select-none',
            isMetaSelected
              ? 'bg-accent/20 border-l-2 border-accent text-white'
              : 'hover:bg-bg-hover text-text-primary',
          ]"
          @click="selectMeta"
        >
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class="text-accent shrink-0"
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="2" y1="12" x2="22" y2="12" />
            <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
          </svg>
          <span class="truncate font-medium">{{ sceneMetaLabel }}</span>
          <!-- v3.4.1: scene 级字段校验警示标（与 floor/prop 行同款 warning 三角） -->
          <button
            v-if="sceneMetaError"
            class="inline-flex items-center justify-center w-4 h-4 rounded
                   text-warning hover:bg-warning/20
                   transition-colors cursor-pointer ml-auto shrink-0"
            :title="sceneMetaError.summary"
            @click.stop="handleSceneMetaErrorClick()"
          >
            <svg
              width="12"
              height="12"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            >
              <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z" />
              <line x1="12" y1="9" x2="12" y2="13" />
              <line x1="12" y1="17" x2="12.01" y2="17" />
            </svg>
          </button>
        </div>

        <!-- Floor 分组 -->
        <div class="mt-3">
          <div
            class="flex items-center gap-1 h-7 px-2 text-text-secondary rounded-md
                   hover:bg-bg-hover cursor-pointer transition-colors select-none"
            @click="floorExpanded = !floorExpanded"
          >
            <component
              :is="floorExpanded ? IconCollapse : IconExpand"
              :size="12"
              class="text-text-subtle flex-shrink-0 transition-transform duration-100"
            />
            <IconFloor :size="14" class="text-type-floor flex-shrink-0" />
            <span class="font-medium">地面</span>
            <span class="ml-1 text-[10px] text-text-subtle">
              ({{ sceneStore.sceneConfig.floor.length }})
            </span>
            <!-- v3.1.0: 标题行右侧的"+新增"小按钮已移除；创建入口由列表下方的常驻大 CTA 承担 -->
          </div>

          <div v-show="floorExpanded">
            <!-- 列表（空或非空都渲染，空时此块不产生节点） -->
            <template v-if="sceneStore.sceneConfig.floor.length > 0">
              <div
                v-for="item in sceneStore.sceneConfig.floor"
                :key="item.id"
                :class="[
                  'group flex items-center gap-1.5 h-7 px-2 pl-6 rounded-md cursor-pointer transition-colors',
                  isFloorSelected(item.id)
                    ? 'bg-accent/20 border-l-2 border-accent text-white'
                    : 'hover:bg-bg-hover text-text-secondary',
                ]"
                :data-tour="isFloorSelected(item.id) ? 'selected-item' : undefined"
                :title="`${item.name || item.id || '未命名地面'} · 双击聚焦`"
                @click="selectFloor(item.id)"
                @dblclick="focusFloor(item.id)"
              >
                <IconFloor :size="12" class="text-type-floor flex-shrink-0" />
                <span class="flex-1 truncate">
                  {{ item.name || item.id || '未命名地面' }}
                </span>
                <!-- v3.4.0: 字段校验警示标（仅有错时渲染，warning 色错开 danger 红） -->
                <button
                  v-if="getFloorError(item.id)"
                  class="inline-flex items-center justify-center w-4 h-4 rounded
                         text-warning hover:bg-warning/20
                         transition-colors cursor-pointer"
                  :title="getFloorError(item.id)!.summary"
                  @click.stop="handleFloorErrorClick(item.id)"
                >
                  <svg
                    width="12"
                    height="12"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                    stroke-linecap="round"
                    stroke-linejoin="round"
                  >
                    <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z" />
                    <line x1="12" y1="9" x2="12" y2="13" />
                    <line x1="12" y1="17" x2="12.01" y2="17" />
                  </svg>
                </button>
                <!-- 次级动作：删除（ghost + hover 显示，LL-007 抑制原则） -->
                <button
                  class="hidden group-hover:inline-flex items-center justify-center w-4 h-4 rounded
                         text-text-subtle hover:text-danger hover:bg-danger/10
                         transition-colors cursor-pointer"
                  title="删除"
                  @click.stop="removeFloor(item.id, item.name)"
                >
                  <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.5">
                    <line x1="2" y1="2" x2="8" y2="8" />
                    <line x1="8" y1="2" x2="2" y2="8" />
                  </svg>
                </button>
              </div>
            </template>

            <!-- 常驻 CTA（v3.1.0）：无论列表是否为空都显示，文案按 空/非空/创建中 三态切换 -->
            <button
              data-tour="create-btn"
              :disabled="!canCreate"
              :title="canCreate
                ? (isCreatingFloor ? '点击取消当前创建' : '新增地面（框选一块区域）')
                : '请先加载场景'"
              :class="[
                'w-full mx-0 mt-1 h-8 flex items-center justify-center gap-1.5 px-3',
                'rounded-md text-[11px] font-medium transition-colors duration-100',
                !canCreate
                  ? 'bg-type-floor/10 text-type-floor/50 cursor-not-allowed'
                  : isCreatingFloor
                  ? 'bg-type-floor/30 text-type-floor cursor-pointer'
                  : 'bg-type-floor/15 text-type-floor hover:bg-type-floor/25 cursor-pointer',
              ]"
              @click="handleAddFloorClick"
            >
              <template v-if="isCreatingFloor">
                <span class="inline-block w-1.5 h-1.5 rounded-full bg-type-floor animate-pulse" />
                <span>框选中… 请在 Viewport 中拖拽选区</span>
              </template>
              <template v-else>
                <IconFloor :size="12" />
                <span>
                  {{ sceneStore.sceneConfig.floor.length === 0 ? '新增第一个地面' : '+ 新增地面' }}
                </span>
              </template>
            </button>
          </div>
        </div>

        <!-- Prop 分组（结构与 Floor 一致） -->
        <div class="mt-3">
          <div
            class="flex items-center gap-1 h-7 px-2 text-text-secondary rounded-md
                   hover:bg-bg-hover cursor-pointer transition-colors select-none"
            @click="propExpanded = !propExpanded"
          >
            <component
              :is="propExpanded ? IconCollapse : IconExpand"
              :size="12"
              class="text-text-subtle flex-shrink-0 transition-transform duration-100"
            />
            <IconProp :size="14" class="text-type-prop flex-shrink-0" />
            <span class="font-medium">对象</span>
            <span class="ml-1 text-[10px] text-text-subtle">
              ({{ sceneStore.sceneConfig.prop.length }})
            </span>
            <!-- v3.1.0: 标题行右侧的"+新增"小按钮已移除；创建入口由列表下方的常驻大 CTA 承担 -->
          </div>

          <div v-show="propExpanded">
            <!-- 列表（空时此块不产生节点） -->
            <template v-if="sceneStore.sceneConfig.prop.length > 0">
              <div
                v-for="item in sceneStore.sceneConfig.prop"
                :key="item.id"
                :class="[
                  'group flex items-center gap-1.5 h-7 px-2 pl-6 rounded-md cursor-pointer transition-colors',
                  isPropSelected(item.id)
                    ? 'bg-accent/20 border-l-2 border-accent text-white'
                    : 'hover:bg-bg-hover text-text-secondary',
                ]"
                :data-tour="isPropSelected(item.id) ? 'selected-item' : undefined"
                :title="`${item.name || item.id || '未命名对象'} · 双击聚焦`"
                @click="selectProp(item.id)"
                @dblclick="focusProp(item.id)"
              >
                <IconProp :size="12" class="text-type-prop flex-shrink-0" />
                <span class="flex-1 truncate">
                  {{ item.name || item.id || '未命名对象' }}
                </span>
                <!-- v3.4.0: 字段校验警示标（同 floor 行规则） -->
                <button
                  v-if="getPropError(item.id)"
                  class="inline-flex items-center justify-center w-4 h-4 rounded
                         text-warning hover:bg-warning/20
                         transition-colors cursor-pointer"
                  :title="getPropError(item.id)!.summary"
                  @click.stop="handlePropErrorClick(item.id)"
                >
                  <svg
                    width="12"
                    height="12"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                    stroke-linecap="round"
                    stroke-linejoin="round"
                  >
                    <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z" />
                    <line x1="12" y1="9" x2="12" y2="13" />
                    <line x1="12" y1="17" x2="12.01" y2="17" />
                  </svg>
                </button>
                <span
                  class="text-[9px] text-text-subtle font-normal shrink-0 mr-1"
                >
                  {{ PROP_CATEGORY_LABELS[item.category] }}
                </span>
                <button
                  class="hidden group-hover:inline-flex items-center justify-center w-4 h-4 rounded
                         text-text-subtle hover:text-danger hover:bg-danger/10
                         transition-colors cursor-pointer"
                  title="删除"
                  @click.stop="removeProp(item.id, item.name)"
                >
                  <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.5">
                    <line x1="2" y1="2" x2="8" y2="8" />
                    <line x1="8" y1="2" x2="2" y2="8" />
                  </svg>
                </button>
              </div>
            </template>

            <!-- 常驻 CTA（v3.1.0）：无论列表是否为空都显示，文案按 空/非空/创建中 三态切换 -->
            <button
              :disabled="!canCreate"
              :title="canCreate
                ? (isCreatingProp ? '点击取消当前创建' : '新增对象（框选一块区域）')
                : '请先加载场景'"
              :class="[
                'w-full mx-0 mt-1 h-8 flex items-center justify-center gap-1.5 px-3',
                'rounded-md text-[11px] font-medium transition-colors duration-100',
                !canCreate
                  ? 'bg-type-prop/10 text-type-prop/50 cursor-not-allowed'
                  : isCreatingProp
                  ? 'bg-type-prop/30 text-type-prop cursor-pointer'
                  : 'bg-type-prop/15 text-type-prop hover:bg-type-prop/25 cursor-pointer',
              ]"
              @click="handleAddPropClick"
            >
              <template v-if="isCreatingProp">
                <span class="inline-block w-1.5 h-1.5 rounded-full bg-type-prop animate-pulse" />
                <span>框选中… 请在 Viewport 中拖拽选区</span>
              </template>
              <template v-else>
                <IconProp :size="12" />
                <span>
                  {{ sceneStore.sceneConfig.prop.length === 0 ? '新增第一个对象' : '+ 新增对象' }}
                </span>
              </template>
            </button>
          </div>
        </div>
      </div>

      <!-- ========== Tab: 元数据（只读 meta 节点） ========== -->
      <div
        v-else-if="activeTab === 'meta'"
        class="flex-1 min-h-0 pt-2 overflow-y-auto text-xs"
      >
        <!-- 空态 -->
        <div
          v-if="metaNodes.length === 0"
          class="py-8 text-center text-text-muted text-[11px] leading-relaxed"
        >
          暂无元数据节点<br />
          <span class="text-text-subtle">加载 meta.json 后会显示</span>
        </div>

        <template v-else>
          <div
            class="flex items-center gap-1 h-7 px-2 text-text-secondary rounded-md
                   hover:bg-bg-hover cursor-pointer transition-colors select-none"
            @click="sceneRootExpanded = !sceneRootExpanded"
          >
            <component
              :is="sceneRootExpanded ? IconCollapse : IconExpand"
              :size="12"
              class="text-text-subtle flex-shrink-0"
            />
            <IconFolder :size="14" class="text-accent flex-shrink-0" />
            <span class="font-medium">Scene Root</span>
            <span class="ml-auto text-[10px] text-text-subtle">{{ metaNodes.length }}</span>
          </div>

          <div v-show="sceneRootExpanded">
            <div
              v-for="node in metaNodes"
              :key="node.id"
              :class="[
                'flex items-center gap-1.5 h-7 px-2 pl-7 rounded-md cursor-pointer transition-colors',
                isMetaNodeSelected(node.id)
                  ? 'bg-accent/20 border-l-2 border-accent text-white'
                  : 'hover:bg-bg-hover text-text-secondary',
              ]"
              @click="selectMetaNode(node.id)"
            >
              <IconLink :size="14" class="text-accent flex-shrink-0" />
              <span class="flex-1 truncate">
                {{ node.name }}
                <span class="text-[10px] text-text-subtle ml-1">
                  · {{ node.summary }}
                </span>
              </span>
            </div>
          </div>
        </template>
      </div>
      </template>

      <!-- v3.4.2: 未加载场景时的中央引导空态（与顶部 CTA 不重复，避免双 CTA 抢焦点） -->
      <template v-else>
        <div
          class="flex-1 flex items-center justify-center px-6 py-12
                 text-center text-text-muted text-[11px] leading-relaxed select-none"
        >
          <div>
            尚未加载场景<br />
            <span class="text-text-subtle">请先在上方打开场景 URL</span>
          </div>
        </div>
      </template>
    </div>
  </FloatingPanel>
</template>
