<!--
  ExportErrorDialog — 配置校验错误提示对话框（导出 / 导入共用）

  - 受控组件（v-model:visible）
  - 接收 errors 数组，按路径分组展示
  - title 可定制，默认"导出校验未通过"，导入侧传"导入校验未通过"复用此 Dialog
  - 单一关闭动作（遵循 LL-007 主役原则）
  - CLARIFY Q5 决策：Dialog 而非 Toast，错误列表完整可见
  - 本期不做「点击跳转到错误字段」（NON-GOAL）

  @changelog
  | 版本   | 变更说明                                                                                   | 关联                                                                         |
  | v1.0.0 | 初始实现：scene-config 导出校验错误列表（按 path 分组）                                      | REQ: 20260422-splat-studio-scene-config-editor TECH: 04_design_tech-design.md §3.4.9 |
  | v1.1.0 | 新增 title 可选 prop（默认"导出校验未通过"）：让导入流程能用同一 Dialog 展示校验错误，避免增加重复 UI | REQ: 文件菜单 — 导入场景配置 |

  @author v_djlzhou
-->
<script setup lang="ts">
import { computed } from 'vue'
import type { ConfigValidationError } from '../../utils/sceneConfigValidator'

const props = withDefaults(
  defineProps<{
    visible: boolean
    errors: ConfigValidationError[]
    /**
     * Header 文案；默认"导出校验未通过"。
     * 导入流程传 "导入校验未通过" 复用同一 Dialog。
     */
    title?: string
  }>(),
  {
    title: '导出校验未通过',
  },
)

const emit = defineEmits<{
  (e: 'update:visible', value: boolean): void
}>()

/** 按照 "Meta / Floor[N] / Prop[N] / Bounds" 分组，让用户一眼看到问题密度 */
interface ErrorGroup {
  title: string
  items: ConfigValidationError[]
}

const groupedErrors = computed<ErrorGroup[]>(() => {
  const metaItems: ConfigValidationError[] = []
  const boundsItems: ConfigValidationError[] = []
  const floorGroups = new Map<number, ConfigValidationError[]>()
  const propGroups = new Map<number, ConfigValidationError[]>()

  for (const err of props.errors) {
    const p = err.path
    if (p === 'bounds') {
      boundsItems.push(err)
    } else if (p === 'sceneId' || p === 'name' || p === 'description') {
      metaItems.push(err)
    } else {
      const floorMatch = /^floor\[(\d+)\]/.exec(p)
      const propMatch = /^prop\[(\d+)\]/.exec(p)
      if (floorMatch) {
        const idx = Number(floorMatch[1])
        if (!floorGroups.has(idx)) floorGroups.set(idx, [])
        floorGroups.get(idx)!.push(err)
      } else if (propMatch) {
        const idx = Number(propMatch[1])
        if (!propGroups.has(idx)) propGroups.set(idx, [])
        propGroups.get(idx)!.push(err)
      } else {
        // 未识别前缀的错误统一归 Meta
        metaItems.push(err)
      }
    }
  }

  const groups: ErrorGroup[] = []
  if (metaItems.length > 0) groups.push({ title: '场景信息 (Meta)', items: metaItems })
  if (boundsItems.length > 0) groups.push({ title: '场景边界 (Bounds)', items: boundsItems })

  // 按 index 升序
  const sortedFloorIdx = [...floorGroups.keys()].sort((a, b) => a - b)
  for (const idx of sortedFloorIdx) {
    groups.push({ title: `地面 floor[${idx}]`, items: floorGroups.get(idx)! })
  }
  const sortedPropIdx = [...propGroups.keys()].sort((a, b) => a - b)
  for (const idx of sortedPropIdx) {
    groups.push({ title: `对象 prop[${idx}]`, items: propGroups.get(idx)! })
  }
  return groups
})

function close() {
  emit('update:visible', false)
}

function onKeydown(e: KeyboardEvent) {
  if (e.key === 'Escape') close()
}
</script>

<template>
  <Teleport to="body">
    <div
      v-if="visible"
      class="fixed inset-0 z-[1000] flex items-center justify-center bg-black/50 backdrop-blur-sm"
      @click.self="close"
      @keydown="onKeydown"
    >
      <div
        class="w-[560px] max-w-[90vw] max-h-[80vh] bg-[#242428] border border-border-strong rounded-lg shadow-dropdown
               flex flex-col overflow-hidden"
        role="dialog"
        aria-modal="true"
      >
        <!-- Header -->
        <div class="flex items-center justify-between h-10 px-4 border-b border-border">
          <div class="flex items-center gap-2">
            <span class="inline-block w-1.5 h-1.5 rounded-full bg-red-400 shrink-0" />
            <span class="text-sm font-semibold text-text-primary">
              {{ title }}
              <span class="text-text-subtle font-normal ml-1">
                · {{ errors.length }} 个问题
              </span>
            </span>
          </div>
          <button
            class="w-6 h-6 flex items-center justify-center text-text-subtle hover:text-text-primary
                   hover:bg-bg-hover rounded transition-colors cursor-pointer"
            aria-label="关闭"
            @click="close"
          >
            ✕
          </button>
        </div>

        <!-- Body: 错误列表（按路径分组） -->
        <div class="flex-1 min-h-0 overflow-y-auto p-4 flex flex-col gap-4">
          <div v-if="errors.length === 0" class="text-xs text-text-muted">
            （没有错误）
          </div>

          <div
            v-for="(group, gi) in groupedErrors"
            :key="gi"
            class="flex flex-col gap-1.5"
          >
            <div class="text-2xs uppercase tracking-wide text-text-subtle font-medium">
              {{ group.title }}
            </div>
            <ul class="flex flex-col gap-1">
              <li
                v-for="(err, ei) in group.items"
                :key="ei"
                class="flex items-start gap-2 text-xs text-red-300 bg-red-500/10 border border-red-500/30
                       rounded px-2 py-1.5"
              >
                <span class="inline-block mt-0.5 text-red-400">⚠</span>
                <div class="flex-1 min-w-0">
                  <code class="text-2xs font-mono text-red-400 mr-2">{{ err.path }}</code>
                  <span class="text-text-primary">{{ err.message }}</span>
                </div>
              </li>
            </ul>
          </div>
        </div>

        <!-- Footer: 单一关闭动作（LL-007 主役原则） -->
        <div
          class="flex items-center justify-end gap-2 h-12 px-4 border-t border-border bg-[#1a1a1d]"
        >
          <button
            class="h-7 px-4 text-xs text-white bg-accent rounded hover:bg-accent-hover
                   transition-colors cursor-pointer font-medium"
            @click="close"
          >
            关闭
          </button>
        </div>
      </div>
    </div>
  </Teleport>
</template>
